    const c = document.createElement('canvas'); c.width = img.width; c.height = img.height
    const ctx = c.getContext('2d'); ctx.drawImage(img, 0, 0)
    const px = (x, y) => { const d = ctx.getImageData(x, y, 1, 1).data; return `#${[d[0],d[1],d[2]].map(v=>v.toString(16).padStart(2,'0')).join('')}` }
    const samples = {}
    // sample a grid
    const pts = { top: [img.width/2, 5], bg1:[10,300], card1:[img.width/2, 200], heroBlue:[150,150] }
    return { w: img.width, h: img.height }
  }, b64)
  console.log(k, JSON.stringify(res))
}
await browser.close()

