/** 底部主导航路由映射（5 tab） */
const TAB_ROUTES: Record<string, string> = {
  home: '/pages/home/index',
  workbench: '/pages/workbench/index',
  housing: '/pages/housing/index',
  data: '/pages/data/index',
}

/** 处理底部导航点击。个人中心走退出登录弹窗。 */
export function useMainNav() {
  function go(key: string) {
    if (key === 'mine') {
      uni.showModal({
        title: '退出登录',
        content: '确定退出当前账号吗？',
        success: res => {
          if (!res.confirm) return
          useFloodStore().logout()
          uni.reLaunch({ url: '/pages/login/index' })
        },
      })
      return
    }
    const url = TAB_ROUTES[key]
    if (!url) return
    uni.reLaunch({ url })
  }
  return { go }
}

