import { chromium } from '@playwright/test'
const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE })
const p = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
await p.route(/font|woff2?|\.ttf|\.otf/i, r=>r.abort()).catch(()=>{})
// go to workbench, click 个人中心 bottom nav
await p.goto('http://127.0.0.1:8095/#/pages/workbench/index', { waitUntil:'domcontentloaded' }); await p.waitForTimeout(1200)
const navTexts = await p.locator('.bottom-nav-item').allInnerTexts()
console.log('workbench bottom nav:', JSON.stringify(navTexts))
await p.getByText('个人中心', { exact: true }).first().click()
await p.waitForTimeout(1000)
const url1 = p.url()
const hasMine = await p.locator('.user-card').count()
console.log('after tap 个人中心 -> url:', url1, 'mine user-card count:', hasMine)
// click logout -> modal -> confirm
await p.locator('.logout-btn').click(); await p.waitForTimeout(500)
const modalVisible = await p.locator('uni-modal, .uni-modal').count()
console.log('logout modal count:', modalVisible)
// click confirm 确定
const confirm = p.getByText('确定', { exact: true }).first()
if(await confirm.count()){ await confirm.click(); await p.waitForTimeout(1000) }
console.log('after logout url:', p.url())
const hasLogin = await p.getByText('苏州市服务监管平台').count()
console.log('login page brand count:', hasLogin)
await browser.close()
